import random, time, collections, math

def is_simple(edges):
    s=set()
    for a,b in edges:
        if a==b: return False
        if a>b: a,b=b,a
        if (a,b) in s: return False
        s.add((a,b))
    return True

def girth(n, edges):
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    g=10**9
    for s in range(n):
        dist=[-1]*n; par=[-1]*n
        dist[s]=0
        dq=collections.deque([s])
        while dq:
            u=dq.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; dq.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g, dist[u]+dist[v]+1)
    return g if g<10**9 else None

def random_regular(n,d):
    stubs=[]
    for i in range(n): stubs += [i]*d
    for attempt in range(100):
        random.shuffle(stubs)
        edges=[]; ok=True; seen=set()
        for i in range(0,len(stubs),2):
            a,b=stubs[i],stubs[i+1]
            if a==b: ok=False; break
            if a>b: a,b=b,a
            if (a,b) in seen: ok=False; break
            seen.add((a,b)); edges.append((a,b))
        if ok: return edges
    return None

