from collections import deque

def lcf(n, pattern, reps):
    edges=set()
    # cycle
    for i in range(n):
        a,b=i,(i+1)%n
        if a>b:a,b=b,a
        edges.add((a,b))
    shifts=(pattern*reps)[:n]
    for i,s in enumerate(shifts):
        j=(i+s)%n
        a,b=i,j
        if a>b:a,b=b,a
        edges.add((a,b))
    return edges

def check(n,edges):
    deg=[0]*n
    adj=[[] for _ in range(n)]
    for u,v in edges:
        deg[u]+=1; deg[v]+=1; adj[u].append(v); adj[v].append(u)
    g=999
    for s in range(n):
        dist=[-1]*n; par=[-1]*n; dist[s]=0; dq=deque([s])
        while dq:
            u=dq.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; dq.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g,dist[u]+dist[v]+1)
    return len(edges), sorted(set(deg)), min(deg), max(deg), (g if g<999 else None), sorted(edges)
